class RefreshCatalog implements Illuminate\Contracts\Queue\ShouldQueue, Illuminate\Contracts\Queue\ShouldBeUniqueUntilProcessing
{
    use Illuminate\Foundation\Queue\Queueable;

    public function uniqueId(): string
    {
        return 'catalog';
    }

